import { useState } from 'react'
import { Check, ListChecks } from 'lucide-react'

interface PlanOption {
  id: string
  label: string
  description?: string | null
}

interface ChoicePanelProps {
  options: PlanOption[]
  onSelect: (optionId: string) => void
}

export function ChoicePanel({ options, onSelect }: ChoicePanelProps) {
  const [selected, setSelected] = useState<string | null>(null)
  const [submitted, setSubmitted] = useState(false)

  const handleConfirm = () => {
    if (!selected) return
    setSubmitted(true)
    onSelect(selected)
  }

  const handleOptionClick = (id: string) => {
    if (submitted) return
    setSelected(prev => prev === id ? null : id)
  }

  return (
    <div style={{
      margin: '12px 0', borderRadius: 12, overflow: 'hidden',
      background: 'var(--bg-surface)',
      border: '1px solid var(--accent-blue, #5a9cf6)',
      boxShadow: '0 0 0 1px rgba(90,156,246,0.2), 0 4px 24px rgba(0,0,0,0.3)',
      animation: 'slideUp 0.25s ease',
    }}>
      {/* Header */}
      <div style={{
        display: 'flex', alignItems: 'center', gap: 10,
        padding: '12px 16px',
        background: 'rgba(90,156,246,0.08)',
        borderBottom: '1px solid rgba(90,156,246,0.2)',
      }}>
        <div style={{
          width: 34, height: 34, borderRadius: 9, flexShrink: 0,
          background: 'rgba(90,156,246,0.15)', border: '1px solid rgba(90,156,246,0.3)',
          display: 'flex', alignItems: 'center', justifyContent: 'center',
        }}>
          <ListChecks size={17} color="var(--accent-blue, #5a9cf6)" />
        </div>
        <div style={{ flex: 1, minWidth: 0 }}>
          <div style={{ fontSize: 14, fontWeight: 600, color: 'var(--text-1)', marginBottom: 1 }}>
            请选择
          </div>
          <div style={{ fontSize: 11, color: 'var(--text-3)' }}>
            点击选择一个方案，然后确认
          </div>
        </div>
      </div>

      {/* Options */}
      <div style={{
        padding: '12px 16px', display: 'flex', flexDirection: 'column', gap: 8,
        background: 'var(--bg-raised)',
      }}>
        {options.map(opt => {
          const isSel = selected === opt.id
          return (
            <button
              key={opt.id}
              onClick={() => handleOptionClick(opt.id)}
              disabled={submitted}
              style={{
                display: 'flex', alignItems: 'flex-start', gap: 10,
                width: '100%', padding: '10px 12px',
                borderRadius: 8, border: isSel
                  ? '2px solid var(--accent-blue, #5a9cf6)'
                  : '1px solid var(--border)',
                background: isSel
                  ? 'rgba(90,156,246,0.08)'
                  : 'var(--bg-surface)',
                cursor: submitted ? 'default' : 'pointer',
                textAlign: 'left',
                transition: 'all 0.15s',
                opacity: submitted && !isSel ? 0.4 : 1,
              }}
            >
              {/* Radio indicator */}
              <div style={{
                width: 18, height: 18, borderRadius: '50%', flexShrink: 0,
                border: isSel ? '2px solid var(--accent-blue, #5a9cf6)' : '2px solid var(--text-3)',
                background: isSel ? 'var(--accent-blue, #5a9cf6)' : 'transparent',
                display: 'flex', alignItems: 'center', justifyContent: 'center',
                marginTop: 1,
              }}>
                {isSel && <Check size={11} color="#fff" strokeWidth={3} />}
              </div>
              <div>
                <div style={{ fontSize: 13, fontWeight: 600, color: 'var(--text-1)' }}>
                  {opt.label}
                </div>
                {opt.description && (
                  <div style={{ fontSize: 11, color: 'var(--text-3)', marginTop: 3, lineHeight: 1.4 }}>
                    {opt.description}
                  </div>
                )}
              </div>
            </button>
          )
        })}
      </div>

      {/* Action */}
      <div style={{
        padding: '10px 16px', display: 'flex', gap: 8, justifyContent: 'flex-end',
        background: 'var(--bg-surface)',
      }}>
        <button
          onClick={handleConfirm}
          disabled={!selected || submitted}
          style={{
            display: 'flex', alignItems: 'center', gap: 5,
            padding: '8px 20px', borderRadius: 8, fontSize: 12, fontWeight: 600,
            background: selected ? 'var(--accent-blue, #5a9cf6)' : 'var(--bg-overlay)',
            border: 'none',
            color: selected ? '#fff' : 'var(--text-3)',
            cursor: selected && !submitted ? 'pointer' : 'not-allowed',
            transition: 'all 0.15s',
          }}
        >
          <Check size={14} />
          {submitted ? '已确认' : '确认选择'}
        </button>
      </div>
    </div>
  )
}

project.frontend/src/components/chat/DeliveryRep:
import { useState, type ComponentType } from 'react'
import {
  AlertTriangle, Check, Circle, Clipboard, Download, FileText, PauseCircle, Terminal, XCircle,
} from 'lucide-react'
import type { DeliveryCommand, DeliveryOutcome, DeliveryReport as DeliveryReportData } from '../../lib/types'
import { stripAnsi } from '../../lib/utils'
import './DeliveryReport.css'

const OUTCOMES: Record<DeliveryOutcome, { label: string; icon: ComponentType<{ size?: number }>; tone: string }> = {
  completed: { label: '运行已结束', icon: Circle, tone: 'completed' },
  failed: { label: '运行失败', icon: XCircle, tone: 'failed' },
  interrupted: { label: '运行已中断', icon: PauseCircle, tone: 'interrupted' },
  incomplete: { label: '交付不完整', icon: AlertTriangle, tone: 'incomplete' },
}

function timestamp(value: number): number {
  return value < 1_000_000_000_000 ? value * 1000 : value
}

function formatDuration(seconds: number): string {
  if (seconds < 1) return `${Math.round(seconds * 1000)}ms`
  if (seconds < 60) return `${seconds.toFixed(1)}s`
  return `${Math.floor(seconds / 60)}m ${Math.round(seconds % 60)}s`
}

function reportDuration(report: DeliveryReportData): string {
  return formatDuration(Math.max(0, timestamp(report.finished_at) - timestamp(report.started_at)) / 1000)
}

function commandResult(command: DeliveryCommand): { label: string; tone: string } {
  if (command.cancelled) return { label: '已取消', tone: 'cancelled' }
  if (command.timed_out) return { label: '超时', tone: 'failed' }
  if (command.exit_code === null) return { label: '退出码未知', tone: 'unknown' }
  if (command.exit_code !== 0) return { label: `退出码 ${command.exit_code}`, tone: 'failed' }
  return { label: '退出码 0', tone: 'passed' }
}

function fileStatus(status: string): string {
  switch (status.toLowerCase()) {
    case 'a': case 'added': case 'create': case 'created': return '新增'
    case 'm': case 'modified': case 'modify': return '修改'
    case 'd': case 'deleted': case 'delete': return '删除'
    case 'r': case 'renamed': case 'rename': return '重命名'
    case 'untracked': case '??': return '未跟踪'
    default: return status || '变更'
  }
}

function summaryText(report: DeliveryReportData): string {
  const outcome = OUTCOMES[report.outcome].label
  const lines = [
    `交付结果：${outcome}（运行状态不代表任务验收通过）`,
    `运行：${report.run_id}`,
    `完成时间：${new Date(timestamp(report.finished_at)).toLocaleString('zh-CN')}`,
    `耗时：${reportDuration(report)}`,
    `基线：${report.base_sha ?? '未记录'}`,
    `Token：输入 ${report.usage.input_tokens} / 输出 ${report.usage.output_tokens}`,
    `文件变更（${report.files.length}）：`,
    ...(report.files.length
      ? report.files.map(file => `- [${fileStatus(file.status)}] ${file.path}`)
      : ['- 无记录']),
    `执行记录（${report.commands.length}）：`,
    ...(report.commands.length
      ? report.commands.map(command => `- ${command.command} — ${commandResult(command).label}`)
      : ['- 未验证：没有执行记录']),
  ]
  if (report.warnings.length) lines.push('警告：', ...report.warnings.map(warning => `- ${warning}`))
  return lines.join('\n')
}

async function copyText(value: string): Promise<void> {
  if (navigator.clipboard?.writeText) {
    await navigator.clipboard.writeText(value)
    return
  }
  const textarea = document.createElement('textarea')
  textarea.value = value
  textarea.style.position = 'fixed'
  textarea.style.opacity = '0'
  document.body.appendChild(textarea)
  textarea.select()
  const copied = document.execCommand('copy')
  textarea.remove()
  if (!copied) throw new Error('copy failed')
}

function downloadReport(report: DeliveryReportData): void {
  const url = URL.createObjectURL(new Blob([JSON.stringify(report, null, 2)], { type: 'application/json' }))
  const link = document.createElement('a')
  link.href = url
  link.download = `delivery-${report.run_id.replace(/[^a-zA-Z0-9._-]/g, '_')}.json`
  document.body.appendChild(link)
  link.click()
  link.remove()
  window.setTimeout(() => URL.revokeObjectURL(url), 0)
}

export function DeliveryReport({ report }: { report: DeliveryReportData }) {
  const [copyState, setCopyState] = useState<'idle' | 'copied' | 'failed'>('idle')
  const outcome = OUTCOMES[report.outcome]
  const OutcomeIcon = outcome.icon

  const copySummary = async () => {
    try {
      await copyText(summaryText(report))
      setCopyState('copied')
      window.setTimeout(() => setCopyState('idle'), 1800)
    } catch {
      setCopyState('failed')
    }
  }

  return (
    <article className={`delivery-report is-${outcome.tone}`} aria-labelledby={`delivery-${report.run_id}`}>
      <header className="delivery-report-header">
        <span className="delivery-report-outcome-icon"><OutcomeIcon size={16} /></span>
        <div className="delivery-report-heading">
          <div className="delivery-report-title-row">
            <h3 id={`delivery-${report.run_id}`}>交付报告</h3>
            <span className="delivery-report-outcome">{outcome.label}</span>
          </div>
          <p>记录本次运行的实际交付；运行结束不代表任务验收通过。</p>
        </div>
        <div className="delivery-report-actions">
          <button type="button" onClick={() => void copySummary()} title="复制交付摘要">
            {copyState === 'copied' ? <Check size={13} /> : <Clipboard size={13} />}
            {copyState === 'copied' ? '已复制' : copyState === 'failed' ? '复制失败' : '复制摘要'}
          </button>
          <button type="button" onClick={() => downloadReport(report)} title="下载完整 JSON">
            <Download size={13} />JSON
          </button>
        </div>
      </header>

      <div className="delivery-report-meta">
        <span title={report.run_id}>运行 <code>{report.run_id.slice(0, 12)}</code></span>
        <span>{new Date(timestamp(report.finished_at)).toLocaleString('zh-CN')}</span>
        <span>耗时 {reportDuration(report)}</span>
        <span>Token {report.usage.input_tokens} → {report.usage.output_tokens}</span>
        <span title={report.base_sha ?? undefined}>基线 {report.base_sha ? report.base_sha.slice(0, 10) : '未记录'}</span>
      </div>

      {report.warnings.length > 0 && (
        <div className="delivery-report-warnings" role="alert">
          <AlertTriangle size={14} />
          <ul>{report.warnings.map((warning, index) => <li key={`${warning}-${index}`}>{warning}</li>)}</ul>
        </div>
      )}

      <section className="delivery-report-section">
        <h4><FileText size={13} />文件变更 <span>{report.files.length}</span></h4>
        {report.files.length > 0 ? (
          <ul className="delivery-files">
            {report.files.map((file, index) => (
              <li key={`${file.path}-${index}`}>
                <span title={`原始状态：${file.status}`}>{fileStatus(file.status)}</span>
                <code>{file.path}</code>
              </li>
            ))}
          </ul>
        ) : <p className="delivery-empty">没有记录到文件变更。</p>}
      </section>

      <section className="delivery-report-section">
        <h4><Terminal size={13} />执行记录 <span>{report.commands.length}</span></h4>
        {report.commands.length === 0 ? (
          <p className="delivery-unverified"><AlertTriangle size={13} />未验证：本次运行没有命令执行记录。</p>
        ) : (
          <div className="delivery-commands">
            {report.commands.map((command, index) => {
              const result = commandResult(command)
              const hasLog = !!(command.stdout || command.stderr)
              return (
                <div className="delivery-command" key={`${command.tool_use_id}-${index}`}>
                  <div className="delivery-command-summary">
                    <code>{command.command}</code>
                    {command.duration !== undefined && <span>{formatDuration(command.duration)}</span>}
                    <span className={`delivery-command-result is-${result.tone}`}>{result.label}</span>
                  </div>
                  {hasLog && (
                    <details>
                      <summary>展开日志</summary>
                      {command.stdout && <pre><strong>stdout</strong>{'\n'}{stripAnsi(command.stdout)}</pre>}
                      {command.stderr && <pre className="is-stderr"><strong>stderr</strong>{'\n'}{stripAnsi(command.stderr)}</pre>}
                    </details>
                  )}
                </div>
              )
            })}
          </div>
        )}
      </section>

      <details className="delivery-diff">
        <summary>查看 diff {report.diff ? '' : '（未记录）'}</summary>
        {report.diff
          ? <pre>{report.diff}</pre>
          : <p className="delivery-empty">本次交付没有可展示的 diff。</p>}
      </details>
    </article>
  )
}

project.frontend/src/components/chat/MessageBubb:
import ReactMarkdown from 'react-markdown'
import remarkGfm from 'remark-gfm'
import { Shrink, Brain, Loader2, FileText, Pencil, Terminal, Search, FolderOpen, ListTree, MemoryStick, Wrench } from 'lucide-react'
import { useState, useEffect } from 'react'
import type { ChatMessage, ContentBlock, AssistantStep } from '../../lib/types'
import type { ToolCall } from '../../hooks/useChat'
import { stripAnsi } from '../../lib/utils'

interface MessageBubbleProps {
  msg: ChatMessage
}

function formatTokens(n: number): string {
  if (n >= 1000) return `${(n / 1000).toFixed(1)}K`
  return String(n)
}

function renderContent(content: string | ContentBlock[]): React.ReactNode {
  if (typeof content === 'string') {
    return <ReactMarkdown remarkPlugins={[remarkGfm]}>{content || ' '}</ReactMarkdown>
  }
  return (
    <>
      {content.map((block, i) => {
        if (block.type === 'text') {
          return <ReactMarkdown key={i} remarkPlugins={[remarkGfm]}>{block.text || ' '}</ReactMarkdown>
        }
        if (block.type === 'image') {
          return (
            <img
              key={i}
              src={`data:${block.source.media_type};base64,${block.source.data}`}
              alt="attached"
              style={{ maxWidth: '100%', maxHeight: 360, borderRadius: 8, margin: '8px 0' }}
            />
          )
        }
        return null
      })}
    </>
  )
}

// ── Tool description helpers ──────────────────────────────

function getToolDescriptor(name: string, input: Record<string, unknown>): { icon: React.ReactNode; action: string; detail: string } {
  const iconSm = { size: 12, style: { flexShrink: 0, marginTop: 2 } }
  switch (name) {
    case 'read_file': {
      const p = String(input.path ?? input.filename ?? '')
      return { icon: <FileText {...iconSm} color="var(--green)" />, action: '读取', detail: p }
    }
    case 'write_file':
    case 'create_file':
    case 'save_file': {
      const p = String(input.path ?? input.filename ?? '')
      return { icon: <Pencil {...iconSm} color="var(--blue)" />, action: '写入', detail: p }
    }
    case 'edit_file': {
      const p = String(input.path ?? input.filename ?? '')
      return { icon: <Pencil {...iconSm} color="var(--blue)" />, action: '编辑', detail: p }
    }
    case 'list_files': {
      const p = String(input.path ?? input.directory ?? '')
      return { icon: <FolderOpen {...iconSm} color="var(--green)" />, action: '列出', detail: p || '当前目录' }
    }
    case 'glob': {
      const p = String(input.pattern ?? '')
      return { icon: <Search {...iconSm} color="var(--green)" />, action: '搜索文件', detail: p }
    }
    case 'grep': {
      const p = String(input.query ?? input.pattern ?? '')
      return { icon: <Search {...iconSm} color="var(--green)" />, action: '搜索内容', detail: p }
    }
    case 'bash':
    case 'background_run': {
      const cmd = String(input.command ?? '').replace(/\n/g, ' ').slice(0, 80)
      return { icon: <Terminal {...iconSm} color="var(--yellow)" />, action: '执行', detail: cmd }
    }
    case 'task': {
      const p = String(input.prompt ?? '').replace(/\n/g, ' ').slice(0, 60)
      return { icon: <Wrench {...iconSm} color="var(--accent)" />, action: '子任务', detail: p }
    }
    case 'TodoWrite': {
      const items = (input.items ?? input.todos) as Array<{ content: string }> | undefined
      return { icon: <ListTree {...iconSm} color="var(--accent)" />, action: '任务列表', detail: `${items?.length ?? 0} 项` }
    }
    case 'memory_store': {
      const p = String(input.key ?? input.name ?? '')
      return { icon: <MemoryStick {...iconSm} color="var(--accent)" />, action: '保存记忆', detail: p }
    }
    case 'memory_recall': {
      const p = String(input.query ?? '')
      return { icon: <MemoryStick {...iconSm} color="var(--accent)" />, action: '回忆记忆', detail: p }
    }
    default: {
      const keys = Object.keys(input)
      const detail = keys.length > 0 ? String(input[keys[0]]).slice(0, 40) : ''
      return { icon: <Wrench {...iconSm} color="var(--text-3)" />, action: name, detail }
    }
  }
}

function formatDuration(seconds: number): string {
  if (seconds < 1) return `${Math.round(seconds * 1000)}ms`
  return `${seconds.toFixed(1)}s`
}

// ── Inline tool call line ──────────────────────────────

function ToolLine({ tc }: { tc: ToolCall }) {
  const [expanded, setExpanded] = useState(false)
  const { icon, action, detail } = getToolDescriptor(tc.name, tc.input)
  const dur = tc.duration ?? (tc.ts_end !== undefined ? tc.ts_end - tc.ts_start : null)
  const isRunning = tc.status === 'running'
  const resultLabel = tc.status === 'error' ? '失败' : tc.status === 'cancelled' ? '已取消' : null

  return (
    <div style={{ marginTop: 5 }}>
      <button
        onClick={() => setExpanded(e => !e)}
        style={{
          display: 'flex', alignItems: 'center', gap: 6,
          width: '100%', padding: '4px 8px', borderRadius: 6,
          background: isRunning ? 'var(--accent-soft)' : tc.status === 'error' ? 'rgba(239,68,68,0.08)' : 'var(--bg-base)',
          border: '1px solid var(--border)',
          cursor: 'pointer', textAlign: 'left',
          fontSize: 12, color: 'var(--text-2)',
          transition: 'background 0.15s',
        }}
      >
        {isRunning ? (
          <span style={{ display: 'inline-flex', animation: 'spin 0.8s linear infinite' }}>
            <Loader2 size={12} color="var(--accent)" />
          </span>
        ) : (
          icon
        )}
        <span style={{ fontWeight: 500 }}>{action}</span>
        <span style={{
          color: 'var(--text-3)', flex: 1,
          overflow: 'hidden', textOverflow: 'ellipsis', whiteSpace: 'nowrap',
          fontFamily: 'var(--font-mono)', fontSize: 11,
        }}>
          {detail}
        </span>
        {dur !== null && (
          <span style={{ color: 'var(--text-3)', fontSize: 10, flexShrink: 0 }}>{formatDuration(dur)}</span>
        )}
        {isRunning && (
          <span style={{ color: 'var(--accent)', fontSize: 10, flexShrink: 0, animation: 'pulse 1s ease-in-out infinite' }}>执行中</span>
        )}
        {resultLabel && (
          <span style={{ color: tc.status === 'error' ? 'var(--red)' : 'var(--text-3)', fontSize: 10, flexShrink: 0 }}>{resultLabel}</span>
        )}
      </button>
      {expanded && !isRunning && tc.output && (
        <pre style={{
          margin: '4px 0 0', padding: '6px 10px', borderRadius: 6,
          background: 'var(--bg-base)', border: '1px solid var(--border)',
          fontSize: 11, fontFamily: 'var(--font-mono)',
          color: tc.status === 'error' ? 'var(--red)' : 'var(--text-2)',
          whiteSpace: 'pre-wrap', wordBreak: 'break-all',
          maxHeight: 160, overflow: 'auto',
        }}>
          {stripAnsi(tc.output.slice(0, 2000))}
        </pre>
      )}
    </div>
  )
}

// ── Thinking block with timer ───────────────────────────

function ThinkingBlock({ text, streaming }: { text: string; streaming?: boolean }) {
  const [open, setOpen] = useState(!!streaming)
  const [elapsed, setElapsed] = useState(0)

  useEffect(() => {
    if (streaming) {
      const startedAt = Date.now()
      const resetTimer = window.setTimeout(() => setElapsed(0), 0)
      const timer = setInterval(() => {
        setElapsed(Math.floor((Date.now() - startedAt) / 1000))
      }, 200)
      return () => {
        window.clearTimeout(resetTimer)
        clearInterval(timer)
      }
    }
  }, [streaming])

  const effectiveOpen = streaming ? true : open

  return (
    <div style={{ marginTop: 6, fontSize: 12 }}>
      <button
        onClick={() => setOpen(o => !o)}
        style={{
          display: 'inline-flex', alignItems: 'center', gap: 5,
          padding: '3px 9px', borderRadius: 6,
          background: streaming ? 'rgba(139,92,246,0.08)' : 'var(--bg-raised)',
          border: streaming ? '1px solid rgba(139,92,246,0.2)' : '1px solid var(--border)',
          color: 'var(--text-3)', cursor: 'pointer', fontSize: 11,
        }}
      >
        {streaming ? (
          <span style={{ display: 'inline-flex', animation: 'spin 0.8s linear infinite' }}>
            <Loader2 size={11} color="var(--accent)" />
          </span>
        ) : (
          <Brain size={11} />
        )}
        <span>{streaming ? `思考中 ${elapsed}s` : `思考了 ${elapsed || Math.max(1, Math.floor(text.length / 50))}s`}</span>
        {effectiveOpen ? (
          <svg width="10" height="10" viewBox="0 0 24 24" fill="none" stroke="currentColor" strokeWidth="2"><path d="m6 9 6 6 6-6" /></svg>
        ) : (
          <svg width="10" height="10" viewBox="0 0 24 24" fill="none" stroke="currentColor" strokeWidth="2"><path d="m9 18 6-6-6-6" /></svg>
        )}
      </button>
      {effectiveOpen && (
        <div style={{
          marginTop: 4, padding: '8px 10px', borderRadius: 6,
          background: 'var(--bg-base)', border: '1px solid var(--border)',
          fontSize: 12, color: 'var(--text-2)', whiteSpace: 'pre-wrap',
          lineHeight: 1.5, maxHeight: 300, overflow: 'auto',
          animation: 'slideUp 0.12s ease',
        }}>
          {text.slice(0, 5000)}
        </div>
      )}
    </div>
  )
}

// ── Step renderer ───────────────────────────────────────

function StepView({ step, streaming }: { step: AssistantStep; streaming: boolean }) {
  if (step.type === 'thinking') {
    return <ThinkingBlock text={step.text || ''} streaming={streaming} />
  }
  if (step.type === 'tool_call' && step.toolCall) {
    return <ToolLine tc={step.toolCall} />
  }
  return null
}

// ── Summary ─────────────────────────────────────────────

function SummaryCardView({ data }: { data: { input_tokens: number; output_tokens: number; tool_rounds: number; file_operations: number } }) {
  return (
    <span style={{
      display: 'inline-flex', alignItems: 'center', gap: 8,
      fontSize: 10, color: 'var(--text-3)',
      background: 'var(--bg-raised)', border: '1px solid var(--border)',
      padding: '2px 10px', borderRadius: 999,
      fontFamily: 'var(--font-mono)',
      marginLeft: 8, verticalAlign: 'middle',
    }}>
      <span title="input/output tokens">
        {formatTokens(data.input_tokens ?? 0)}→{formatTokens(data.output_tokens ?? 0)}
      </span>
      <span style={{ color: 'var(--border-hi)' }}>|</span>
      <span title="tool rounds">
        {data.tool_rounds ?? 0} 工具
      </span>
      <span style={{ color: 'var(--border-hi)' }}>|</span>
      <span title="file operations">
        {data.file_operations ?? 0} 文件
      </span>
    </span>
  )
}

// ── Main component ──────────────────────────────────────

export function MessageBubble({ msg }: MessageBubbleProps) {
  const isUser = msg.role === 'user'
  const isSystem = msg.role === 'system'

  if (isSystem) {
    const textContent = typeof msg.content === 'string' ? msg.content : ''
    return (
      <div style={{ display: 'flex', justifyContent: 'center', margin: '8px 0' }}>
        <span style={{
          display: 'flex', alignItems: 'center', gap: 5,
          fontSize: 11, color: 'var(--text-3)',
          background: 'var(--bg-raised)', border: '1px solid var(--border)',
          padding: '3px 12px', borderRadius: 999,
        }}>
          <Shrink size={11} />
          {textContent}
        </span>
      </div>
    )
  }

  if (isUser) {
    return (
      <div style={{
        display: 'flex', justifyContent: 'flex-end',
        gap: 8, margin: '6px 0',
        animation: 'fadeIn 0.2s ease',
      }}>
        <div style={{ maxWidth: '80%', display: 'flex', flexDirection: 'column', alignItems: 'flex-end', gap: 3 }}>
          <div style={{
            background: 'var(--accent-soft)',
            border: '1px solid var(--accent-border)',
            padding: '9px 14px',
            borderRadius: '14px 4px 14px 14px',
            color: 'var(--text-1)', fontSize: 14, lineHeight: 1.6,
            whiteSpace: 'pre-wrap',
            boxShadow: 'var(--shadow-sm)',
          }}>
            {renderContent(msg.content)}
          </div>
          <span style={{ fontSize: 10, color: 'var(--text-3)' }}>
            {new Date(msg.ts).toLocaleTimeString('zh-CN', { hour: '2-digit', minute: '2-digit' })}
          </span>
        </div>
        <div style={{
          width: 26, height: 26, borderRadius: 8, flexShrink: 0,
          background: 'var(--bg-overlay)', border: '1px solid var(--border-hi)',
          display: 'flex', alignItems: 'center', justifyContent: 'center',
          fontSize: 11, fontWeight: 700, color: 'var(--text-2)',
          marginTop: 2, boxShadow: 'var(--shadow-sm)',
        }}>
          U
        </div>
      </div>
    )
  }

  // Assistant message — use steps for chronological rendering
  const steps = msg.steps
  const hasContent = typeof msg.content === 'string' ? msg.content.length > 0 : msg.content.length > 0

  return (
    <div style={{
      display: 'flex', gap: 8, margin: '4px 0',
      animation: 'fadeIn 0.2s ease',
    }}>
      <div style={{
        width: 26, height: 26, borderRadius: 8, flexShrink: 0,
        background: 'linear-gradient(135deg, var(--accent) 0%, var(--accent-2) 100%)',
        display: 'flex', alignItems: 'center', justifyContent: 'center',
        fontSize: 11, fontWeight: 700, color: '#fff', marginTop: 2,
        boxShadow: 'var(--shadow-sm), inset 0 1px 0 rgba(255,255,255,.18)',
      }}>
        A
      </div>
      <div style={{ flex: 1, minWidth: 0 }}>
        {/* Steps timeline: thinking + tool calls in order */}
        {steps && steps.length > 0 && (
          <div style={{
            marginBottom: hasContent ? 8 : 0,
            borderLeft: '2px solid var(--border)',
            paddingLeft: 10,
          }}>
            {steps.map((step, i) => {
              const isLast = i === steps.length - 1
              const contentStarted = hasContent || msg.toolCalls?.some(tc => tc.status === 'done')
              const isStepStreaming = step.type === 'thinking'
                ? !!(msg.streaming && isLast && !contentStarted)
                : step.type === 'tool_call' && step.toolCall?.status === 'running'
              return <StepView key={i} step={step} streaming={isStepStreaming} />
            })}
          </div>
        )}

        {/* Fallback for messages without steps (restored from history) */}
        {!steps && msg.thinking && <ThinkingBlock text={msg.thinking} streaming={msg.streaming} />}
        {!steps && msg.toolCalls && msg.toolCalls.length > 0 && (
          <div style={{ marginBottom: hasContent ? 8 : 0 }}>
            {msg.toolCalls.map(tc => <ToolLine key={tc.id} tc={tc} />)}
          </div>
        )}

        {/* Final text content */}
        {hasContent && (
          <div className="md-content" style={{ fontSize: 14, lineHeight: 1.7 }}>
            {renderContent(msg.content)}
            {msg.streaming && msg.thinking === undefined && (
              <span style={{
                display: 'inline-block', width: 2, height: 14,
                background: 'var(--accent)',
                marginLeft: 2, verticalAlign: 'middle',
                animation: 'pulse 1s ease-in-out infinite',
              }} />
            )}
          </div>
        )}

        <div style={{ fontSize: 10, color: 'var(--text-3)', marginTop: hasContent || (steps && steps.length > 0) ? 4 : 0, display: 'flex', alignItems: 'center', gap: 8 }}>
          <span>{new Date(msg.ts).toLocaleTimeString('zh-CN', { hour: '2-digit', minute: '2-digit' })}</span>
          {msg.summary && <SummaryCardView data={msg.summary} />}
        </div>
      </div>
    </div>
  )
}

import { useState } from 'react'
import ReactMarkdown from 'react-markdown'
import remarkGfm from 'remark-gfm'
import { FileText, Check, X, MessageSquare, ChevronDown, ChevronUp } from 'lucide-react'

interface PlanReviewProps {
  content: string
  runId: string
  onApprove: (runId: string) => void
  onReject: (runId: string) => void
  onModify: (runId: string, feedback: string) => void
  onCancel?: () => void
}

export function PlanReview({ content, runId, onApprove, onReject, onModify, onCancel }: PlanReviewProps) {
  const [expanded, setExpanded] = useState(true)
  const [modifyMode, setModifyMode] = useState(false)
  const [feedback, setFeedback] = useState('')

  const handleModify = () => {
    if (!feedback.trim()) return
    onModify(runId, feedback.trim())
    setModifyMode(false)
    setFeedback('')
  }

  return (
    <div style={{
      margin: '12px 0', borderRadius: 12, overflow: 'hidden',
      background: 'var(--bg-surface)',
      border: '1px solid var(--accent)',
      boxShadow: '0 0 0 1px var(--accent-border), 0 4px 24px rgba(0,0,0,0.3)',
      animation: 'slideUp 0.25s ease',
    }}>
      {/* Header */}
      <div style={{
        display: 'flex', alignItems: 'center', gap: 10,
        padding: '12px 16px',
        background: 'var(--accent-soft)',
        borderBottom: expanded ? '1px solid var(--accent-border)' : 'none',
      }}>
        <div style={{
          width: 34, height: 34, borderRadius: 9, flexShrink: 0,
          background: 'var(--badge-accent)', border: '1px solid var(--accent-border)',
          display: 'flex', alignItems: 'center', justifyContent: 'center',
        }}>
          <FileText size={17} color="var(--accent)" />
        </div>

        <div style={{ flex: 1, minWidth: 0 }}>
          <div style={{ fontSize: 14, fontWeight: 600, color: 'var(--text-1)', marginBottom: 1 }}>
            实施计划
          </div>
          <div style={{ fontSize: 11, color: 'var(--text-3)' }}>
            智能体已生成详细计划，请审核后决定是否执行
          </div>
        </div>

        <button
          onClick={() => setExpanded(o => !o)}
          style={{
            background: 'none', border: 'none', cursor: 'pointer',
            color: 'var(--text-3)', padding: '4px',
            borderRadius: 4, display: 'flex',
          }}
        >
          {expanded ? <ChevronUp size={16} /> : <ChevronDown size={16} />}
        </button>
      </div>

      {/* Plan content (rendered markdown) */}
      {expanded && (
        <div style={{
          padding: '16px 20px', maxHeight: 400, overflow: 'auto',
          background: 'var(--bg-raised)',
          borderBottom: modifyMode ? 'none' : '1px solid var(--border)',
        }}>
          <div className="md-content" style={{ fontSize: 13 }}>
            <ReactMarkdown remarkPlugins={[remarkGfm]}>{content}</ReactMarkdown>
          </div>
        </div>
      )}

      {/* Modify feedback input */}
      {modifyMode && (
        <div style={{ padding: '12px 16px', background: 'var(--bg-raised)', borderBottom: '1px solid var(--border)' }}>
          <div style={{ display: 'flex', gap: 8 }}>
            <textarea
              autoFocus
              value={feedback}
              onChange={e => setFeedback(e.target.value)}
              onKeyDown={e => {
                if (e.key === 'Enter' && e.ctrlKey) handleModify()
                if (e.key === 'Escape') { setModifyMode(false); setFeedback('') }
              }}
              placeholder="输入修改建议..."
              rows={2}
              style={{
                flex: 1, resize: 'none', background: 'var(--bg-base)',
                border: '1px solid var(--border-hi)', borderRadius: 8,
                padding: '8px 12px', fontSize: 13, color: 'var(--text-1)',
                fontFamily: 'inherit', outline: 'none',
              }}
            />
          </div>
          <div style={{ display: 'flex', gap: 6, marginTop: 8, justifyContent: 'flex-end' }}>
            <button
              onClick={() => { setModifyMode(false); setFeedback('') }}
              style={{
                padding: '5px 12px', borderRadius: 6, fontSize: 11,
                background: 'none', border: '1px solid var(--border)',
                color: 'var(--text-3)', cursor: 'pointer',
              }}
            >
              取消
            </button>
            <button
              onClick={handleModify}
              disabled={!feedback.trim()}
              style={{
                padding: '5px 14px', borderRadius: 6, fontSize: 11, fontWeight: 600,
                background: feedback.trim() ? 'var(--accent)' : 'var(--bg-overlay)',
                border: 'none', color: feedback.trim() ? '#fff' : 'var(--text-3)',
                cursor: feedback.trim() ? 'pointer' : 'not-allowed',
                display: 'flex', alignItems: 'center', gap: 4,
              }}
            >
              <MessageSquare size={12} />
              提交反馈
            </button>
          </div>
        </div>
      )}

      {/* Action buttons */}
      {!modifyMode && (
        <div style={{
          padding: '10px 16px', display: 'flex', gap: 8,
          background: 'var(--bg-surface)',
        }}>
          <button
            onClick={() => onReject(runId)}
            style={{
              display: 'flex', alignItems: 'center', gap: 5,
              padding: '8px 16px', borderRadius: 8, fontSize: 12, fontWeight: 500,
              background: 'var(--bg-raised)', border: '1px solid var(--border)',
              color: 'var(--red)', cursor: 'pointer',
              transition: 'all 0.15s',
            }}
          >
            <X size={14} />
            拒绝，重新规划
          </button>
          <button
            onClick={() => setModifyMode(true)}
            style={{
              display: 'flex', alignItems: 'center', gap: 5,
              padding: '8px 16px', borderRadius: 8, fontSize: 12, fontWeight: 500,
              background: 'var(--bg-raised)', border: '1px solid var(--border)',
              color: 'var(--text-2)', cursor: 'pointer',
              transition: 'all 0.15s',
            }}
          >
            <MessageSquare size={14} />
            修改建议
          </button>
          <div style={{ flex: 1 }} />
          {onCancel && (
            <button
              onClick={onCancel}
              style={{
                padding: '8px 12px', borderRadius: 8, fontSize: 12,
                background: 'none', border: 'none',
                color: 'var(--text-3)', cursor: 'pointer',
              }}
            >
              取消
            </button>
          )}
          <button
            onClick={() => onApprove(runId)}
            style={{
              display: 'flex', alignItems: 'center', gap: 5,
              padding: '8px 20px', borderRadius: 8, fontSize: 12, fontWeight: 600,
              background: 'var(--accent)', border: 'none',
              color: '#fff', cursor: 'pointer',
              transition: 'all 0.15s',
            }}
          >
            <Check size={14} />
            同意，开始执行
          </button>
        </div>
      )}
    </div>
  )
}

